import { en } from './en';

export type Locale = 'es' | 'en';
export const LOCALES: Locale[] = ['es', 'en'];
export const LOCALE_COOKIE = 'nx_locale';

export const isLocale = (v: unknown): v is Locale => v === 'es' || v === 'en';

/** gettext-style lookup: the Spanish source text is the key; `{name}` placeholders are interpolated. */
/** Sentences generated by the API with embedded values. */
const PATTERNS: [RegExp, string][] = [
  [/^El vendedor despachó el paquete con (.+)\.$/, 'The seller shipped the package with $1.'],
  [/^(.+) despachó tu paquete con (.+)\.$/, '$1 shipped your package with $2.'],
  [/^Recoge tu pedido en la tienda del vendedor \((.+)\)$/, 'Pick up your order at the seller’s store ($1)'],
];

export function translate(locale: Locale, es: string, vars?: Record<string, string | number | null | undefined>) {
  let s = locale === 'en' ? (en[es] ?? es) : es;
  if (locale === 'en' && s === es) for (const [re, rep] of PATTERNS) if (re.test(es)) { s = es.replace(re, rep); break; }
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, k) => (vars[k] === undefined || vars[k] === null ? m : String(vars[k])));
  return s;
}

export const intlLocale = (l: Locale) => (l === 'en' ? 'en-US' : 'es-419');
